const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').split(/\s+/).filter(Boolean);
const n = +tokens[0];
const S = tokens.slice(1, n + 1).join('');

function inc(s) {
  const a = s.split('');
  let i = a.length - 1;
  while (i >= 0 && a[i] === '9') { a[i] = '0'; i--; }
  if (i < 0) return '1' + a.join('');
  a[i] = String(+a[i] + 1);
  return a.join('');
}

// Verifica se existe B >= A tal que A, A+1, ..., B concatenados formam S,
// onde A = S[0..k)
function valid(k) {
  if (S[0] === '0') return false;
  let pos = k;
  let cur = S.slice(0, k);
  while (pos < n) {
    const t = inc(cur);
    const rem = n - pos;
    if (rem === t.length) return S.slice(pos) === t;
    if (rem < t.length) return false;
    if (S.slice(pos, pos + t.length) !== t) return false;
    pos += t.length;
    cur = t;
  }
  return true;
}

let ans = S; // fallback: k = n, ou seja, A = B = S inteiro
for (let k = 1; k < n; k++) {
  if (valid(k)) { ans = S.slice(0, k); break; }
}
console.log(ans);
